using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections;using System.Collections.Generic;
using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;
using Autodesk.AutoCAD.PlottingServices;
using App=Autodesk.AutoCAD.ApplicationServices.Application;
public class SignedPrintHostRegression {
 static string root=@"F:\Codedemo\XJG批量打印_fix";static string folder=Path.Combine(root,"local-artifacts","signed-print-host");static BindingFlags flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance;static Assembly asm;static StringBuilder log=new StringBuilder();
 static void Check(bool ok,string reason){if(!ok)throw new System.Exception(reason);}
 static object Call(Type t,string name,params object[] args){try{return t.GetMethod(name,flags).Invoke(null,args);}catch(TargetInvocationException ex){throw ex.InnerException;}}
 static string Run(Func<string> action){return (string)Call(asm.GetType("TitleAttributeBatch.Core.SignatureRuntime",true),"Run",action);}
 static string Hash(string path){using(var input=File.OpenRead(path))using(var sha=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(input));}
 static int Count(Database db){using(var tr=db.TransactionManager.StartTransaction()){var space=(BlockTableRecord)tr.GetObject(db.CurrentSpaceId,OpenMode.ForRead);int n=space.Cast<ObjectId>().Count(id=>((Entity)tr.GetObject(id,OpenMode.ForRead)).Layer=="CAD_签名");tr.Commit();return n;}}
 static void PrintProof(Autodesk.AutoCAD.ApplicationServices.Document doc,string pdf){var db=doc.Database;using(var tr=db.TransactionManager.StartTransaction()){var layout=(Layout)tr.GetObject(LayoutManager.Current.GetLayoutId("Model"),OpenMode.ForRead);using(var settings=new PlotSettings(layout.ModelType)){settings.CopyFrom(layout);var v=PlotSettingsValidator.Current;v.SetPlotConfigurationName(settings,"DWG To PDF.pc3",null);v.RefreshLists(settings);var media=v.GetCanonicalMediaNameList(settings).Cast<string>().First(n=>n.Contains("A3")&&n.Contains("420"));v.SetCanonicalMediaName(settings,media);v.SetPlotWindowArea(settings,new Extents2d(0,0,420,297));v.SetPlotType(settings,Autodesk.AutoCAD.DatabaseServices.PlotType.Window);v.SetUseStandardScale(settings,true);v.SetStdScaleType(settings,StdScaleType.ScaleToFit);v.SetPlotCentered(settings,true);using(var info=new PlotInfo{Layout=layout.ObjectId,OverrideSettings=settings})using(var validator=new PlotInfoValidator{MediaMatchingPolicy=MatchingPolicy.MatchEnabled}){validator.Validate(info);using(var engine=PlotFactory.CreatePublishEngine()){engine.BeginPlot(null,null);engine.BeginDocument(info,doc.Name,null,1,true,pdf);using(var page=new PlotPageInfo()){engine.BeginPage(page,info,true,null);engine.BeginGenerateGraphics(null);engine.EndGenerateGraphics(null);engine.EndPage(null);}engine.EndDocument(null);engine.EndPlot(null);}}}tr.Commit();}Check(File.Exists(pdf)&&new FileInfo(pdf).Length>1000,"Signed PDF was not generated");}
 static ObjectId Frame(Database db,double x,double height){using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForWrite);var def=new BlockTableRecord{Name="普通块_"+Guid.NewGuid().ToString("N")};bt.Add(def);tr.AddNewlyCreatedDBObject(def,true);var line=new Polyline();line.AddVertexAt(0,new Point2d(0,0),0,0,0);line.AddVertexAt(1,new Point2d(420,0),0,0,0);line.AddVertexAt(2,new Point2d(420,height),0,0,0);line.AddVertexAt(3,new Point2d(0,height),0,0,0);line.Closed=true;def.AppendEntity(line);tr.AddNewlyCreatedDBObject(line,true);var space=(BlockTableRecord)tr.GetObject(db.CurrentSpaceId,OpenMode.ForWrite);var frame=new BlockReference(new Point3d(x,0,0),def.ObjectId);space.AppendEntity(frame);tr.AddNewlyCreatedDBObject(frame,true);tr.Commit();return frame.ObjectId;}}
 static object Jobs(params ObjectId[] ids){var type=asm.GetType("ZwcadBatchPlot.PlotJob",true);var list=(IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(type));foreach(var id in ids){var job=Activator.CreateInstance(type);type.GetProperty("SourceFile").SetValue(job,Path.Combine(folder,"original.dwg"),null);type.GetProperty("BlockHandle").SetValue(job,id.Handle.ToString(),null);type.GetProperty("SignBeforePlot").SetValue(job,true,null);list.Add(job);}return list;}
 [CommandMethod("SIGNED_PRINT_TEST")]public void Test(){try{
 asm=Assembly.Load(File.ReadAllBytes(Path.Combine(root,"local-artifacts","installer-v32","HP","AutoCAD2015-2024","AcadBatchPlot.Runtime.dll")));
 var paths=asm.GetType("ZwcadBatchPlot.PluginRuntimePaths",true);string profile=Path.Combine(folder,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(profile);paths.GetProperty("BaseDirectory",flags).SetValue(null,profile,null);
 var commands=asm.GetType("CadSignature.Commands",true);
 bool rejected=false;try{Run(()=>{Call(commands,"ValidatePlotSigning");return "";});}catch(InvalidOperationException e){rejected=e.Message.Contains("人员设置");}Check(rejected,"Missing personnel config accepted");log.AppendLine("PASS missing personnel configuration rejected before printing");
 Run(()=>{string session=(string)asm.GetType("CadSignature.CoreEntry",true).GetField("BaseDirectory",flags).GetValue(null);File.WriteAllText(Path.Combine(session,"人员名单.txt"),"项目负责人=\n专业负责人=\n审定=\n审核=\n校对=\n设计=测试人员|test.dwg\n制图=\n",new UTF8Encoding(false));return "";});
 rejected=false;try{Run(()=>{Call(commands,"ValidatePlotSigning");return "";});}catch(InvalidOperationException e){rejected=e.Message.Contains("标定");}Check(rejected,"Missing calibration accepted");log.AppendLine("PASS missing calibration rejected");
 Run(()=>{string session=(string)asm.GetType("CadSignature.CoreEntry",true).GetField("BaseDirectory",flags).GetValue(null);File.WriteAllText(Path.Combine(session,"图框定位.txt"),"A3@RB=297,-100,10,-10,80",new UTF8Encoding(false));string signature=Path.Combine(folder,"test-signature.dwg");using(var db=new Database(true,true)){using(var tr=db.TransactionManager.StartTransaction()){var space=(BlockTableRecord)tr.GetObject(db.CurrentSpaceId,OpenMode.ForWrite);var line=new Line(Point3d.Origin,new Point3d(10,4,0));space.AppendEntity(line);tr.AddNewlyCreatedDBObject(line,true);tr.Commit();}db.SaveAs(signature,DwgVersion.Current);}Call(asm.GetType("CadSignature.SignatureVault",true),"Save",Path.Combine(session,"Signatures"),"test.dwg",File.ReadAllBytes(signature));return "";});
 var doc=App.DocumentManager.MdiActiveDocument;var dbMain=doc.Database;var one=Frame(dbMain,0,297);var other=Frame(dbMain,600,297);var bad=Frame(dbMain,1200,100);
 ObjectId oldSignature;using(var tr=dbMain.TransactionManager.StartTransaction()){var layers=(LayerTable)tr.GetObject(dbMain.LayerTableId,OpenMode.ForWrite);var layer=new LayerTableRecord{Name="CAD_签名"};layers.Add(layer);tr.AddNewlyCreatedDBObject(layer,true);var space=(BlockTableRecord)tr.GetObject(dbMain.CurrentSpaceId,OpenMode.ForWrite);var old=new DBText{TextString="原有签名",Position=new Point3d(330,60,0),Height=2,LayerId=layer.ObjectId};oldSignature=space.AppendEntity(old);tr.AddNewlyCreatedDBObject(old,true);tr.Commit();}
 string source=Path.Combine(folder,"original.dwg");dbMain.SaveAs(source,DwgVersion.Current);string original=Hash(source);
 ObjectId unsaved;using(var tr=dbMain.TransactionManager.StartTransaction()){var space=(BlockTableRecord)tr.GetObject(dbMain.CurrentSpaceId,OpenMode.ForWrite);var text=new DBText{TextString="保留未保存修改",Position=new Point3d(0,400,0),Height=4};unsaved=space.AppendEntity(text);tr.AddNewlyCreatedDBObject(text,true);tr.Commit();}
 int before=Count(dbMain);var scopeType=asm.GetType("ZwcadBatchPlot.TemporarySignedPlotScope",true);
 for(int pass=0;pass<2;pass++){
  string backupPath;try{using(var scope=(IDisposable)Call(scopeType,"Begin",doc,Jobs(one))){var backup=scopeType.GetField("backup",flags).GetValue(scope);backupPath=(string)backup.GetType().GetProperty("BackupPath",flags).GetValue(backup,null);Check(File.Exists(backupPath)&&Hash(backupPath)==original,"Original backup invalid");Check(Count(dbMain)>before,"No temporary signature entities");using(var tr=dbMain.TransactionManager.StartTransaction()){var space=(BlockTableRecord)tr.GetObject(dbMain.CurrentSpaceId,OpenMode.ForRead);foreach(ObjectId id in space){var e=(Entity)tr.GetObject(id,OpenMode.ForRead);if(e.Layer=="CAD_签名")Check(e.GeometricExtents.MaxPoint.X<600,"Unselected frame was signed");}tr.Commit();}if(pass==0)PrintProof(doc,Path.Combine(folder,"signed-proof.pdf"));if(pass==1)throw new OperationCanceledException();}Check(!File.Exists(backupPath),"Backup not cleaned after rollback");}catch(OperationCanceledException){}
  Check(Count(dbMain)==before,"Temporary signatures not rolled back");Check(Hash(source)==original,"Original file changed");Check(!oldSignature.IsErased,"Original signature was not restored");using(var tr=dbMain.TransactionManager.StartTransaction())Check(((DBText)tr.GetObject(unsaved,OpenMode.ForRead)).TextString=="保留未保存修改","Unsaved edits lost");
 }
 log.AppendLine("PASS selected arbitrary-name frame signed; unselected frame untouched; actual signed PDF engine output inside rollback scope; success and cancellation rollback; original bytes and unsaved edits preserved");
 rejected=false;try{using(var scope=(IDisposable)Call(scopeType,"Begin",doc,Jobs(one,bad))){} }catch(InvalidOperationException){rejected=true;}Check(rejected&&Count(dbMain)==before&&Hash(source)==original,"Partial-signature failure did not roll back");log.AppendLine("PASS unsupported frame calibration stops file and rolls back partial signatures");
 }catch(System.Exception ex){log.AppendLine("FAIL "+ex);}File.WriteAllText(Path.Combine(folder,"result.txt"),log.ToString(),Encoding.UTF8);}
